sites.find:
cRSubLoc* row_end =
    cell + sizeof(runtime_cells[0]) / sizeof(runtime_cells[0][0]);
do {
    cell->Remove();
    ++cell;
} while (cell != row_end);

replacements.text:
lane_count =
    sizeof(runtime_cells[0]) / sizeof(runtime_cells[0][0]);
do {
    cell->Remove();
    ++cell;
    --lane_count;
} while (lane_count != 0);
